CREATE     PROCEDURE [synapse_fo].[usp_Update_VENDTRANS]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:30:55
	Description: Update stored procedure for VENDTRANS from synapse finops datalake to BI
*/
BEGIN
	UPDATE tgt SET 
		tgt.[ACCOUNTINGEVENT] = stg.[ACCOUNTINGEVENT],
		tgt.[ACCOUNTNUM] = stg.[ACCOUNTNUM],
		tgt.[AMOUNTCUR] = stg.[AMOUNTCUR],
		tgt.[AMOUNTMST] = stg.[AMOUNTMST],
		tgt.[APPROVED] = stg.[APPROVED],
		tgt.[APPROVEDDATE] = stg.[APPROVEDDATE],
		tgt.[APPROVER] = stg.[APPROVER],
		tgt.[ARRIVAL] = stg.[ARRIVAL],
		tgt.[ARRIVALACCOUNTID] = stg.[ARRIVALACCOUNTID],
		tgt.[BANKCENTRALBANKPURPOSECODE] = stg.[BANKCENTRALBANKPURPOSECODE],
		tgt.[BANKCENTRALBANKPURPOSETEXT] = stg.[BANKCENTRALBANKPURPOSETEXT],
		tgt.[BANKLCIMPORTLINE] = stg.[BANKLCIMPORTLINE],
		tgt.[BANKREMITTANCEFILEID] = stg.[BANKREMITTANCEFILEID],
		tgt.[CANCEL] = stg.[CANCEL],
		tgt.[CASHDISCBASEDATE] = stg.[CASHDISCBASEDATE],
		tgt.[CASHDISCCODE] = stg.[CASHDISCCODE],
		tgt.[CLOSED] = stg.[CLOSED],
		tgt.[COMPANYBANKACCOUNTID] = stg.[COMPANYBANKACCOUNTID],
		tgt.[CORRECT] = stg.[CORRECT],
		tgt.[CREATEDBY] = stg.[CREATEDBY],
		tgt.[CREATEDDATETIME] = stg.[CREATEDDATETIME],
		tgt.[CREATEDTRANSACTIONID] = stg.[CREATEDTRANSACTIONID],
		tgt.[CURRENCYCODE] = stg.[CURRENCYCODE],
		tgt.[DATAAREAID] = stg.[DATAAREAID],
		tgt.[DataLakeModified_DateTime] = stg.[DataLakeModified_DateTime],
		tgt.[DEFAULTDIMENSION] = stg.[DEFAULTDIMENSION],
		tgt.[DOCUMENTDATE] = stg.[DOCUMENTDATE],
		tgt.[DOCUMENTNUM] = stg.[DOCUMENTNUM],
		tgt.[DUEDATE] = stg.[DUEDATE],
		tgt.[EUROTRIANGULATION] = stg.[EUROTRIANGULATION],
		tgt.[EXCHADJUSTMENT] = stg.[EXCHADJUSTMENT],
		tgt.[EXCHADJUSTMENTREPORTING] = stg.[EXCHADJUSTMENTREPORTING],
		tgt.[EXCHRATE] = stg.[EXCHRATE],
		tgt.[EXCHRATESECOND] = stg.[EXCHRATESECOND],
		--tgt.[FileName] = stg.[FileName],
		tgt.[FIXEDEXCHRATE] = stg.[FIXEDEXCHRATE],
		tgt.[INVOICE] = stg.[INVOICE],
		tgt.[INVOICEPROJECT] = stg.[INVOICEPROJECT],
		tgt.[INVOICERELEASEDATE] = stg.[INVOICERELEASEDATE],
		--tgt.[INVOICERELEASEDATETZID] = stg.[INVOICERELEASEDATETZID],
		tgt.[JOURNALNUM] = stg.[JOURNALNUM],
		tgt.[LASTEXCHADJ] = stg.[LASTEXCHADJ],
		tgt.[LASTEXCHADJRATE] = stg.[LASTEXCHADJRATE],
		tgt.[LASTEXCHADJRATEREPORTING] = stg.[LASTEXCHADJRATEREPORTING],
		tgt.[LASTEXCHADJVOUCHER] = stg.[LASTEXCHADJVOUCHER],
		tgt.[LastProcessedChange_DateTime] = stg.[LastProcessedChange_DateTime],
		tgt.[LASTSETTLEACCOUNTNUM] = stg.[LASTSETTLEACCOUNTNUM],
		tgt.[LASTSETTLECOMPANY] = stg.[LASTSETTLECOMPANY],
		tgt.[LASTSETTLEDATE] = stg.[LASTSETTLEDATE],
		tgt.[LASTSETTLEVOUCHER] = stg.[LASTSETTLEVOUCHER],
		--tgt.[LSN] = stg.[LSN],
		tgt.[MODIFIEDBY] = stg.[MODIFIEDBY],
		tgt.[MODIFIEDDATETIME] = stg.[MODIFIEDDATETIME],
		tgt.[MODIFIEDTRANSACTIONID] = stg.[MODIFIEDTRANSACTIONID],
		tgt.[OFFSETRECID] = stg.[OFFSETRECID],
		tgt.[PARTITION] = stg.[PARTITION],
		tgt.[PAYMID] = stg.[PAYMID],
		tgt.[PAYMMODE] = stg.[PAYMMODE],
		tgt.[PAYMREFERENCE] = stg.[PAYMREFERENCE],
		tgt.[PAYMSPEC] = stg.[PAYMSPEC],
		tgt.[PAYMTERMID] = stg.[PAYMTERMID],
		tgt.[POSTINGPROFILE] = stg.[POSTINGPROFILE],
		tgt.[POSTINGPROFILEAPPROVE] = stg.[POSTINGPROFILEAPPROVE],
		tgt.[POSTINGPROFILECANCEL] = stg.[POSTINGPROFILECANCEL],
		tgt.[POSTINGPROFILECLOSE] = stg.[POSTINGPROFILECLOSE],
		tgt.[POSTINGPROFILEREOPEN] = stg.[POSTINGPROFILEREOPEN],
		tgt.[PREPAYMENT] = stg.[PREPAYMENT],
		tgt.[PROMISSORYNOTEID] = stg.[PROMISSORYNOTEID],
		tgt.[PROMISSORYNOTESEQNUM] = stg.[PROMISSORYNOTESEQNUM],
		tgt.[PROMISSORYNOTESTATUS] = stg.[PROMISSORYNOTESTATUS],
		tgt.[PSNJOURNALIZINGDEFINITION] = stg.[PSNJOURNALIZINGDEFINITION],
		tgt.[PSNPURCHASINGCARDTYPE] = stg.[PSNPURCHASINGCARDTYPE],
		tgt.[RBOVENDTRANS] = stg.[RBOVENDTRANS],
		tgt.[REASONREFRECID] = stg.[REASONREFRECID],
		tgt.[RECID] = stg.[RECID],
		tgt.[RECVERSION] = stg.[RECVERSION],
		tgt.[RELEASEDATECOMMENT] = stg.[RELEASEDATECOMMENT],
		tgt.[REMITTANCEADDRESS] = stg.[REMITTANCEADDRESS],
		tgt.[REMITTANCELOCATION] = stg.[REMITTANCELOCATION],
		tgt.[REPORTINGCURRENCYAMOUNT] = stg.[REPORTINGCURRENCYAMOUNT],
		tgt.[REPORTINGCURRENCYCROSSRATE] = stg.[REPORTINGCURRENCYCROSSRATE],
		tgt.[REPORTINGCURRENCYEXCHRATE] = stg.[REPORTINGCURRENCYEXCHRATE],
		tgt.[REPORTINGCURRENCYEXCHRATESECONDARY] = stg.[REPORTINGCURRENCYEXCHRATESECONDARY],
		tgt.[REPORTINGEXCHADJUSTMENTREALIZED] = stg.[REPORTINGEXCHADJUSTMENTREALIZED],
		tgt.[REPORTINGEXCHADJUSTMENTUNREALIZED] = stg.[REPORTINGEXCHADJUSTMENTUNREALIZED],
		tgt.[SETTLEAMOUNTCUR] = stg.[SETTLEAMOUNTCUR],
		tgt.[SETTLEAMOUNTMST] = stg.[SETTLEAMOUNTMST],
		tgt.[SETTLEAMOUNTREPORTING] = stg.[SETTLEAMOUNTREPORTING],
		tgt.[SETTLEMENT] = stg.[SETTLEMENT],
		tgt.[SETTLETAX1099AMOUNT] = stg.[SETTLETAX1099AMOUNT],
		tgt.[SETTLETAX1099STATEAMOUNT] = stg.[SETTLETAX1099STATEAMOUNT],
		--tgt.[SKS_BR_CLEAREDDATE] = stg.[SKS_BR_CLEAREDDATE],
		tgt.[SUMMARYACCOUNTID] = stg.[SUMMARYACCOUNTID],
		--tgt.[SysRowId] = stg.[SysRowId],
		tgt.[TAX1099AMOUNT] = stg.[TAX1099AMOUNT],
		tgt.[TAX1099DATE] = stg.[TAX1099DATE],
		tgt.[TAX1099FIELDS] = stg.[TAX1099FIELDS],
		tgt.[TAX1099NUM] = stg.[TAX1099NUM],
		tgt.[TAX1099RECID] = stg.[TAX1099RECID],
		tgt.[TAX1099STATE] = stg.[TAX1099STATE],
		tgt.[TAX1099STATEAMOUNT] = stg.[TAX1099STATEAMOUNT],
		tgt.[TAXINVOICEPURCHID] = stg.[TAXINVOICEPURCHID],
		tgt.[THIRDPARTYBANKACCOUNTID] = stg.[THIRDPARTYBANKACCOUNTID],
		tgt.[TRANSDATE] = stg.[TRANSDATE],
		tgt.[TRANSTYPE] = stg.[TRANSTYPE],
		tgt.[TXT] = stg.[TXT],
		tgt.[VENDEXCHADJUSTMENTREALIZED] = stg.[VENDEXCHADJUSTMENTREALIZED],
		tgt.[VENDEXCHADJUSTMENTUNREALIZED] = stg.[VENDEXCHADJUSTMENTUNREALIZED],
		tgt.[VENDORVATDATE] = stg.[VENDORVATDATE],
		tgt.[VENDPAYMENTGROUP] = stg.[VENDPAYMENTGROUP],
		tgt.[VOUCHER] = stg.[VOUCHER]
	 FROM [synapse_fo].[VENDTRANS] tgt
		INNER JOIN [staging_fo].[VENDTRANS] stg
			ON  stg.[RECID] = tgt.[RECID] 
		
END
